const py = `
import re
p="crates/mm-engine/src/builtins.rs"
src=open(p).read()
i=src.find("const DEFS")
j=src.find("];", i)
chunk=src[i:j]
lines=chunk.splitlines()
entries=[]
buf=""
depth=0
start=False
for line in lines:
    if not start:
        if re.match(r"    [nmp]!\\(", line):
            start=True
            buf=line+"\\n"
            depth=line.count("(")-line.count(")")
            if depth==0:
                entries.append(buf)
                buf=""
                start=False
        continue
    buf+=line+"\\n"
    depth+=line.count("(")-line.count(")")
    if depth<=0:
        entries.append(buf)
        buf=""
        start=False
print("entries", len(entries))
rows=[]
for e in entries:
    kind=e.strip()[0]
    if kind=="p":
        name=re.search(r'"([^"]*)"', e).group(1)
        fm=re.search(r',\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*\\)\\s*$', e.strip())
        rows.append(("prelude", name, fm.group(1) if fm else "?"))
    elif kind=="m":
        strs=re.findall(r'"([^"]*)"', e)
        fm=re.search(r',\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*\\)\\s*$', e.strip())
        rows.append(("module:"+strs[0], strs[1], fm.group(1) if fm else "?"))
    else:
        m=re.search(r'n!\\(\\s*"([^"]+)"\\s*,\\s*([^,\\n]+)', e)
        name, owner = m.group(1), m.group(2).strip()
        fm=re.search(r',\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*\\)\\s*$', e.strip())
        fn=fm.group(1) if fm else "?"
        rows.append((owner, name, fn))
print("---FUNCTIONS---")
for o,n,f in rows:
    if o=="None":
        print(f"{n}\\t{f}")
print("---MODULES---")
for o,n,f in rows:
    if o.startswith("module") or o=="prelude":
        print(f"{o}\\t{n}\\t{f}")
print("---METHODS---")
cur=None
for o,n,f in rows:
    if o not in ("None",) and not o.startswith("module") and o!="prelude":
        if o!=cur:
            print(f"# {o}")
            cur=o
        print(f"  {n}\\t{f}")
print("TOTAL", len(rows))
`;
