const py = `
import re
src = open("crates/mm-engine/src/builtins.rs").read()
i = src.find("const DEFS")
j = src.find("];", i)
chunk = src[i:j]
# find macro calls at column 4
pos = 0
entries = []
while True:
    k = chunk.find("\\n    ", pos)
    if k < 0:
        break
    rest = chunk[k+1:]
    m = None
    for prefix in ("    n!(", "    m!(", "    p!("):
        if rest.startswith(prefix):
            m = prefix
            break
    if not m:
        pos = k+1
        continue
    # scan parens from the bang paren
    start = k+1
    p0 = chunk.find("(", start)
    depth = 0
    q = False
    esc = False
    end = None
    for idx in range(p0, len(chunk)):
        c = chunk[idx]
        if q:
            if esc:
                esc = False
            elif c == "\\\\":
                esc = True
            elif c == '"':
                q = False
            continue
        if c == '"':
            q = True
            continue
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                end = idx
                break
    entries.append(chunk[start:end+1])
    pos = end+1
print("entries", len(entries))

def strings(e):
    out = []
    q = False
    esc = False
    cur = ""
    for c in e:
        if q:
            if esc:
                cur += c
                esc = False
            elif c == "\\\\":
                esc = True
            elif c == '"':
                out.append(cur)
                cur = ""
                q = False
            else:
                cur += c
        elif c == '"':
            q = True
    return out

def last_ident(e):
    # identifier before final )
    s = e.rstrip()
    s = s[:-1].rstrip()
    # take trailing ident
    i = len(s)
    while i and (s[i-1].isalnum() or s[i-1] == "_"):
        i -= 1
    return s[i:]

rows = []
for e in entries:
    kind = e.strip()[0]
    ss = strings(e)
    fn = last_ident(e)
    if kind == "p":
        rows.append(("prelude", ss[0], fn))
    elif kind == "m":
        rows.append(("module:"+ss[0], ss[1], fn))
    else:
        # owner token after first comma
        body = e[e.find(",")+1:].lstrip()
        owner = body.split(",")[0].strip()
        rows.append((owner, ss[0], fn))

print("---FUNCTIONS---")
for o,n,f in rows:
    if o == "None":
        print(n + "\\t" + f)
print("---MODULES---")
for o,n,f in rows:
    if o.startswith("module") or o == "prelude":
        print(o + "\\t" + n + "\\t" + f)
print("---METHODS---")
cur = None
for o,n,f in rows:
    if o not in ("None",) and not o.startswith("module") and o != "prelude":
        if o != cur:
            print("# " + o)
            cur = o
        print("  " + n + "\\t" + f)
print("TOTAL", len(rows))
bad = [e[:60].replace("\\n"," ") for e in entries if last_ident(e) in ("", "?")]
print("bad", len(bad))
