import re
src = open("crates/mm-engine/src/builtins.rs").read()
i = src.find("const DEFS")
j = src.find("];", i)
chunk = src[i:j]
pos = 0
entries = []
while True:
    k = chunk.find("\\n    ", pos)
    if k < 0:
        break
    rest = chunk[k+1:]
    matched = False
    for prefix in ("    n!(", "    m!(", "    p!("):
        if rest.startswith(prefix):
            matched = True
            break
    if not matched:
        pos = k+1
        continue
    start = k+1
    p0 = chunk.find("(", start)
    depth = 0
    q = False
    esc = False
    end = None
    for idx in range(p0, len(chunk)):
        c = chunk[idx]
        if q:
            if esc:
                esc = False
            elif c == "\\\\":
                esc = True
            elif c == '"':
                q = False
            continue
        if c == '"':
            q = True
            continue
        if c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0:
                end = idx
                break
    entries.append(chunk[start:end+1])
    pos = end+1

def strings(e):
    out = []
    q = False
    esc = False
    cur = []
    for c in e:
        if q:
            if esc:
                cur.append(c)
                esc = False
            elif c == "\\\\":
                esc = True
            elif c == '"':
                out.append("".join(cur))
                cur = []
                q = False
            else:
                cur.append(c)
        elif c == '"':
            q = True
    return out

def last_ident(e):
    s = e.rstrip()[:-1].rstrip()
    i = len(s)
    while i and (s[i-1].isalnum() or s[i-1] == "_"):
        i -= 1
    return s[i:]

rows = []
for e in entries:
    kind = e.strip()[0]
    ss = strings(e)
    fn = last_ident(e)
    if kind == "p":
        rows.append(("prelude", ss[0], fn))
    elif kind == "m":
        rows.append(("module:"+ss[0], ss[1], fn))
    else:
        body = e[e.find(",")+1:].lstrip()
        owner = body.split(",")[0].strip()
        rows.append((owner, ss[0], fn))

open("/tmp/bi_rows.txt","w").write("")
parts = []
parts.append("entries %d\\n" % len(entries))
parts.append("---FUNCTIONS---\\n")
for o,n,f in rows:
    if o == "None":
        parts.append(n + "\\t" + f + "\\n")
parts.append("---MODULES---\\n")
for o,n,f in rows:
    if o.startswith("module") or o == "prelude":
        parts.append(o + "\\t" + n + "\\t" + f + "\\n")
parts.append("---METHODS---\\n")
cur = None
for o,n,f in rows:
    if o not in ("None",) and not o.startswith("module") and o != "prelude":
        if o != cur:
            parts.append("# " + o + "\\n")
            cur = o
        parts.append("  " + n + "\\t" + f + "\\n")
parts.append("TOTAL %d\\n" % len(rows))
open("/tmp/bi_rows.txt","w").write("".join(parts))
print("".join(parts))
