const py = `
src = open("crates/mm-engine/src/builtins.rs").read().splitlines()
fns = []
for i,line in enumerate(src):
    if line.startswith("fn ") or line.startswith("pub(crate) fn ") or line.startswith("pub fn "):
        name = line.split("fn ",1)[1].split("(")[0].strip()
        fns.append((i, name))
fns.append((len(src), "EOF"))

markers = ("need_py", "dunder_call", "call_request", "prelude_request", "op_user_next", "Request::", "op_get_iter", "slow")
# per function, which markers and which local fns it calls
import re
call_re = re.compile(r"\\b([A-Za-z_][A-Za-z0-9_]*)\\s*\\(")
local = {n for _,n in fns}
bodies = {}
called = {}
marks = {}
for (a,name),(b,_) in zip(fns, fns[1:]):
    body = "\\n".join(src[a:b])
    bodies[name] = body
    ms = [m for m in markers if m in body]
    marks[name] = ms
    cs = []
    for m in call_re.finditer(body):
        c = m.group(1)
        if c in local and c != name:
            cs.append(c)
    called[name] = sorted(set(cs))

# transitive reach of marker functions
seeds = {n for n,ms in marks.items() if any(m in ms for m in ("need_py","dunder_call","call_request","prelude_request","op_user_next","Request::"))}
# also functions that call those
changed = True
reach = set(seeds)
while changed:
    changed = False
    for n,cs in called.items():
        if n not in reach and any(c in reach for c in cs):
            reach.add(n)
            changed = True

# load rows
rows = open("/tmp/bi_rows.txt").read().splitlines()
section = None
interesting = []
for line in rows:
    if line.startswith("---"):
        section = line
        continue
    if section is None or line.startswith("entries") or line.startswith("TOTAL") or line.startswith("#"):
        continue
    if section == "---FUNCTIONS---":
        name, fn = line.split("\\t")
        kind = "function"
        owner = ""
    elif section == "---MODULES---":
        owner, name, fn = line.split("\\t")
        kind = "module"
    elif section == "---METHODS---":
        if not line.startswith("  "):
            continue
        name, fn = line.strip().split("\\t")
        kind = "method"
        owner = ""
    else:
        continue
    if fn in reach:
        why = ",".join(marks.get(fn, []))
        # how: direct or via
        via = [c for c in called.get(fn, []) if c in reach]
        interesting.append((kind, owner, name, fn, why, ",".join(via)))

print("seed count", len(seeds))
print("reach count", len(reach))
print("---DIRECT---")
for n in sorted(seeds):
    print(n, ":", ",".join(marks[n]))
print("---CALLBACKS---")
# dedupe by fn for methods later
seen = set()
for kind, owner, name, fn, why, via in interesting:
    key = (kind, owner, name, fn)
    if key in seen:
        continue
    seen.add(key)
    print(f"{kind}\\t{name}\\t{fn}\\tdirect={why or '-'}\\tvia={via or '-'}")
print("callback entries", len(seen))
`;
