# bits layout fixed high: 0xFFFA at 63..48
# free: kind k0..k7 at bits 40..47, raw r0..r31 at bits 0..31
# bits 32..39 are 0
# xor bit i = (bit (i+4) of bits if i+4<64 else 0) XOR (bit (i-20) of bits if i>=20 else 0)
# We need xor bits 2..63 == 1

# Variable index: 0..7 kind, 8..39 raw

def bit_of_bits(b):
    # returns (const, list of var indices) xor
    if 48 <= b <= 63:
        # constant from 0xFFFA
        const = (0xFFFA >> (b-48)) & 1
        return const, []
    if 40 <= b <= 47:
        return 0, [b-40]  # kind
    if 32 <= b <= 39:
        return 0, []
    if 0 <= b <= 31:
        return 0, [8+b]
    return 0, []

def xor_term(i):
    c1, v1 = (0, [])
    if i+4 < 64:
        c1, v1 = bit_of_bits(i+4)
    c2, v2 = (0, [])
    if i >= 20:
        c2, v2 = bit_of_bits(i-20)
    vars = v1 + v2
    # cancel duplicates (xor)
    from collections import Counter
    cnt = Counter(vars)
    vars = [v for v,n in cnt.items() if n%2==1]
    return (c1^c2), vars

# Gaussian elimination on 62 equations (bits 2..63), 40 vars
# matrix rows: 40 cols + rhs
rows = []
