    # free_bits: list of bit positions that are variables; others constant from hi<<48 pattern... 
    # bits = (hi<<48) | payload, payload bits in free positions within low 48, rest 0
    free = list(free_bits)
    idx = {b:i for i,b in enumerate(free)}
    def bit_expr(b):
        if b >= 48:
            return ((hi >> (b-48)) & 1), []
        if b in idx:
            return 0, [idx[b]]
        return 0, []  # forced 0
