MODULUS = (1 << 61) - 1

def hash_int(i):
    m = MODULUS  # as signed, fits
    if i >= 0:
        h = i % m
    else:
        h = -(((-i) % m))
    if h == -1:
        h = -2
    return h

def frexp(x):
    import math
    # use python math.frexp which matches C
    return math.frexp(x)

def hash_float(v):
    import math
    if math.isnan(v):
        return 0
    if math.isinf(v):
        return 314159 if v > 0 else -314159
    if v == 0.0:
        return 0
    m, e = frexp(v)
    sign = 1
    if m < 0:
        sign = -1
        m = -m
    x = 0
    while m != 0.0:
        x = ((x << 28) & MODULUS) | (x >> (61 - 28))
        m *= 268435456.0
        e -= 28
        y = int(m)  # trunc toward zero? m is positive
        # rust `m as u64` truncates toward zero
        m -= y
        x += y
        if x >= MODULUS:
            x -= MODULUS
    if e >= 0:
        e = e % 61
    else:
        e = 61 - 1 - ((-1 - e) % 61)
    x = ((x << e) & MODULUS) | (x >> (61 - e))
    h = (x * sign)  # mathematical
    # wrap to i64? x < 2^61, sign -1, fits
    if h == -1:
        h = -2
    return h

